namespace krmemory {
namespace {
using json::Value;
std::filesystem::path known(REFKNOWNFOLDERID id){wchar_t* value{};if(SHGetKnownFolderPath(id,0,nullptr,&value)!=S_OK)return{};std::filesystem::path out(value);CoTaskMemFree(value);return out;}
std::string read(const std::filesystem::path& path){std::ifstream input(path,std::ios::binary);return input?std::string((std::istreambuf_iterator<char>(input)),{}):std::string{};}
std::string quote(std::string_view text){std::string out="\"";for(unsigned char c:text){if(c=='\"'||c=='\\'){out+='\\';out+=char(c);}else if(c=='\n')out+="\\n";else if(c=='\r')out+="\\r";else if(c=='\t')out+="\\t";else if(c>=32)out+=char(c);}return out+'\"';}
std::string serialize(const Value& value){if(std::holds_alternative<std::nullptr_t>(value.data))return"null";if(auto p=std::get_if<bool>(&value.data))return*p?"true":"false";if(auto p=std::get_if<double>(&value.data)){std::ostringstream out;out.precision(17);out<<*p;return out.str();}if(auto p=std::get_if<std::string>(&value.data))return quote(*p);if(auto p=std::get_if<Value::Array>(&value.data)){std::string out="[";for(std::size_t i{};i<p->size();++i){if(i)out+=',';out+=serialize((*p)[i]);}return out+"]";}std::string out="{";bool first=true;for(const auto&[key,item]:std::get<Value::Object>(value.data)){if(!first)out+=',';first=false;out+=quote(key)+":"+serialize(item);}return out+"}";}
Value::Object& object(Value& value){if(!value.is_object())value.data=Value::Object{};return std::get<Value::Object>(value.data);}
std::string utf8(const std::filesystem::path& path){auto w=path.wstring();if(w.empty())return{};int n=WideCharToMultiByte(CP_UTF8,0,w.data(),int(w.size()),nullptr,0,nullptr,nullptr);std::string out(std::size_t(n),'\0');WideCharToMultiByte(CP_UTF8,0,w.data(),int(w.size()),out.data(),n,nullptr,nullptr);return out;}
std::string toml(std::string_view text){std::string out="\"";for(auto c:text){if(c=='\\'||c=='\"')out+='\\';out+=c;}return out+'\"';}
std::string section_name(ClientKind kind){return kind==ClientKind::codex?"mcp_servers.kr_mycelia_memory":"kr-mycelia-memory";}
std::string display(ClientKind kind){if(kind==ClientKind::cursor)return"Cursor";if(kind==ClientKind::claude_desktop)return"Claude Desktop";return"Codex";}
std::filesystem::path credential_path(std::string_view agent){auto root=known(FOLDERID_LocalAppData)/L"KRMyceliaNativeMemory"/L"credentials";std::filesystem::create_directories(root);std::string safe;for(unsigned char c:agent)if(std::isalnum(c)||c=='-'||c=='_')safe+=char(c);if(safe.empty())throw std::invalid_argument("invalid agent name");return root/(safe+".dpapi");}
void protect(std::string_view token,const std::filesystem::path& path){if(token.size()!=64)throw std::invalid_argument("invalid MCP token");DATA_BLOB source{DWORD(token.size()),reinterpret_cast<BYTE*>(const_cast<char*>(token.data()))},encrypted{};if(!CryptProtectData(&source,L"KR Mycelia MCP credential",nullptr,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&encrypted))throw std::runtime_error("DPAPI credential protection failed");auto temp=path;temp+=L".tmp";{std::ofstream output(temp,std::ios::binary|std::ios::trunc);output.write(reinterpret_cast<char*>(encrypted.pbData),encrypted.cbData);if(!output){LocalFree(encrypted.pbData);throw std::runtime_error("credential write failed");}}LocalFree(encrypted.pbData);if(!MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){std::filesystem::remove(temp);throw std::runtime_error("credential commit failed");}SetFileAttributesW(path.c_str(),FILE_ATTRIBUTE_HIDDEN|FILE_ATTRIBUTE_NOT_CONTENT_INDEXED);}
void atomic_write(const std::filesystem::path& path,std::string_view content){std::filesystem::create_directories(path.parent_path());auto temp=path;temp+=L".krmycelia.tmp";{std::ofstream output(temp,std::ios::binary|std::ios::trunc);output.write(content.data(),std::streamsize(content.size()));if(!output)throw std::runtime_error("configuration write failed");}if(!MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){std::filesystem::remove(temp);throw std::runtime_error("configuration commit failed");}}
std::string remove_toml_section(std::string text,std::string_view section){std::istringstream input(text);std::string line,out;bool dropping{};const auto header="["+std::string(section)+"]";while(std::getline(input,line)){auto trimmed=line;trimmed.erase(0,trimmed.find_first_not_of(" \t\r"));if(!trimmed.empty()&&trimmed.front()=='[')dropping=trimmed==header;if(!dropping)out+=line+'\n';}return out;}
ClientConnection state(ClientKind kind,const std::filesystem::path& path,bool configured,std::string detail){return{kind,display(kind),true,configured,path,std::move(detail)};}
}

std::vector<ClientConnection> detect_supported_clients(){auto roaming=known(FOLDERID_RoamingAppData),profile=known(FOLDERID_Profile);std::vector<ClientConnection> result;auto add=[&](ClientKind kind,std::filesystem::path config,std::filesystem::path marker){auto data=read(config);bool configured=kind==ClientKind::codex?data.find("[mcp_servers.kr_mycelia_memory]")!=std::string::npos:data.find("\"kr-mycelia-memory\"")!=std::string::npos;result.push_back({kind,display(kind),std::filesystem::exists(marker)||std::filesystem::exists(config),configured,std::move(config),configured?"Verbunden":"Nicht verbunden"});};add(ClientKind::cursor,profile/L".cursor"/L"mcp.json",roaming/L"Cursor");add(ClientKind::claude_desktop,roaming/L"Claude"/L"claude_desktop_config.json",roaming/L"Claude");add(ClientKind::codex,profile/L".codex"/L"config.toml",profile/L".codex");return result;}

ClientConnection connect_client(ClientKind kind,const std::filesystem::path& config,const std::filesystem::path& executable,std::string agent,std::string token){if(!std::filesystem::is_regular_file(executable))throw std::invalid_argument("MCP executable is missing");std::string original=read(config);std::filesystem::path backup=config;backup+=L".krmycelia.bak";if(std::filesystem::exists(config))std::filesystem::copy_file(config,backup,std::filesystem::copy_options::overwrite_existing);auto credential=credential_path(agent);try{protect(token,credential);if(kind==ClientKind::codex){auto merged=remove_toml_section(original,section_name(kind));if(!merged.empty()&&merged.back()!='\n')merged+='\n';merged+="\n[mcp_servers.kr_mycelia_memory]\ncommand = "+toml(utf8(executable))+"\nargs = [\"--agent\", "+toml(agent)+", \"--credential\", "+toml(utf8(credential))+"]\nstartup_timeout_sec = 10\ntool_timeout_sec = 60\n";atomic_write(config,merged);}else{Value root=original.empty()?Value{Value::Object{}}:json::parse(original);auto& servers=object(object(root)["mcpServers"]);Value::Array args{Value{std::string("--agent")},Value{agent},Value{std::string("--credential")},Value{utf8(credential)}};Value::Object entry;entry["command"]=Value{utf8(executable)};entry["args"]=Value{std::move(args)};servers[section_name(kind)]=Value{std::move(entry)};atomic_write(config,serialize(root)+"\n");}}catch(...){if(std::filesystem::exists(backup))std::filesystem::copy_file(backup,config,std::filesystem::copy_options::overwrite_existing);else std::filesystem::remove(config);std::filesystem::remove(credential);throw;}return state(kind,config,true,"Verbunden; Client-Neustart erforderlich");}

ClientConnection disconnect_client(ClientKind kind,const std::filesystem::path& config,std::string_view agent){std::string original=read(config);std::filesystem::path backup=config;backup+=L".krmycelia.disconnect.bak";if(std::filesystem::exists(config))std::filesystem::copy_file(config,backup,std::filesystem::copy_options::overwrite_existing);try{if(kind==ClientKind::codex)atomic_write(config,remove_toml_section(original,section_name(kind)));else if(!original.empty()){auto root=json::parse(original);auto& root_object=object(root);auto it=root_object.find("mcpServers");if(it!=root_object.end()&&it->second.is_object())object(it->second).erase(section_name(kind));atomic_write(config,serialize(root)+"\n");}std::filesystem::remove(credential_path(agent));}catch(...){if(std::filesystem::exists(backup))std::filesystem::copy_file(backup,config,std::filesystem::copy_options::overwrite_existing);throw;}return state(kind,config,false,"Getrennt; andere MCP-Einträge wurden beibehalten");}
}
#else
namespace krmemory {std::vector<ClientConnection> detect_supported_clients(){return{};}ClientConnection connect_client(ClientKind,const std::filesystem::path&,const std::filesystem::path&,std::string,std::string){throw std::runtime_error("Windows only");}ClientConnection disconnect_client(ClientKind,const std::filesystem::path&,std::string_view){throw std::runtime_error("Windows only");}}
#endif
